#pragma once

// Monospace bitmap fonts for FrameBuffer332::text() (data in FbFonts.cpp,
// generated by tools/gen_fonts.py; provenance and licences there).
// Printable ASCII 0x20..0x7E only, row-major, bit 7 = leftmost pixel.

#include <stdint.h>

constexpr int kFontFirstChar = 0x20;
constexpr int kFontLastChar = 0x7E;
constexpr int kFontGlyphs = kFontLastChar - kFontFirstChar + 1;

extern const uint8_t kFont6x8[kFontGlyphs * 8];     // 6 columns x 8 rows
extern const uint8_t kFont8x16[kFontGlyphs * 16];   // 8 columns x 16 rows
